exercises.prompt_markdown:
Predict the printed output of this query:

```sql
CREATE TABLE depts (id INT, name TEXT);
CREATE TABLE staff (id INT, dept_id INT);
INSERT INTO depts VALUES (1, 'Engineering'), (2, 'Marketing'), (3, 'HR');
INSERT INTO staff VALUES (101, 1), (102, 1), (103, 2);

SELECT depts.name 
FROM depts 
LEFT JOIN staff ON depts.id = staff.dept_id 
WHERE staff.id IS NULL;
```

examples.code:
CREATE TABLE customers (id INT, name VARCHAR(50));
CREATE TABLE orders (id INT, customer_id INT, amount INT);
INSERT INTO customers VALUES (1, 'Alice'), (2, 'Bob'), (3, 'Charlie');
INSERT INTO orders VALUES (101, 1, 500), (102, 1, 200), (103, 2, 750);

SELECT customers.name, orders.id AS order_id, orders.amount
FROM customers
INNER JOIN orders ON customers.id = orders.customer_id;

SELECT customers.name, orders.id AS order_id, orders.amount
FROM customers
LEFT JOIN orders ON customers.id = orders.customer_id;

CREATE TABLE staff (id INT, name VARCHAR(50), manager_id INT);
INSERT INTO staff VALUES (1, 'CEO Ada', NULL), (2, 'VP Bob', 1), (3, 'Eng Carol', 2);

SELECT 
    emp.name AS employee,
    COALESCE(mgr.name, 'Top Level') AS manager
FROM staff emp
LEFT JOIN staff mgr ON emp.manager_id = mgr.id;

CREATE TABLE products (id INT, product_name VARCHAR(50));
CREATE TABLE order_items_multi (order_id INT, product_id INT, qty INT);
INSERT INTO products VALUES (501, 'Monitor'), (502, 'Keyboard');
INSERT INTO order_items_multi VALUES (101, 501, 2), (101, 502, 1);

SELECT customers.name, orders.id AS order_id, products.product_name, order_items_multi.qty
FROM customers
JOIN orders ON customers.id = orders.customer_id
JOIN order_items_multi ON orders.id = order_items_multi.order_id
JOIN products ON order_items_multi.product_id = products.id;
